CREATE TABLE IF NOT EXISTS SkuAttribute (Sku TEXT NOT NULL PRIMARY KEY, StyleCode TEXT NOT NULL, CategoryCode TEXT NOT NULL, Brand TEXT NULL, Season TEXT NULL, Discontinued INTEGER NOT NULL DEFAULT 0, UpdatedUtc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS BasePrice (Sku TEXT NOT NULL, Market TEXT NOT NULL, Currency TEXT NOT NULL, Price NUMERIC NOT NULL, UpdatedUtc TEXT NOT NULL, PRIMARY KEY (Sku, Market));
CREATE TABLE IF NOT EXISTS PriceList (Id INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT NOT NULL, Market TEXT NOT NULL, Currency TEXT NOT NULL, ValidFrom TEXT NOT NULL, Status TEXT NOT NULL, CreatedBy TEXT NULL, CreatedUtc TEXT NOT NULL, PublishedUtc TEXT NULL);
CREATE TABLE IF NOT EXISTS PriceListItem (PriceListId INTEGER NOT NULL REFERENCES PriceList (Id) ON DELETE CASCADE, Sku TEXT NOT NULL, Price NUMERIC NOT NULL, CompareAtPrice NUMERIC NULL, PRIMARY KEY (PriceListId, Sku));
CREATE TABLE IF NOT EXISTS EffectivePrice (Sku TEXT NOT NULL, Market TEXT NOT NULL, Price NUMERIC NOT NULL, CompareAtPrice NUMERIC NULL, PriceListId INTEGER NULL, ValidFrom TEXT NOT NULL, PRIMARY KEY (Sku, Market));
CREATE TABLE IF NOT EXISTS Promotion (Id INTEGER PRIMARY KEY AUTOINCREMENT, Code TEXT NOT NULL UNIQUE, Name TEXT NOT NULL, Type TEXT NOT NULL, Channel TEXT NOT NULL, Markets TEXT NOT NULL, StartsUtc TEXT NOT NULL, EndsUtc TEXT NOT NULL, Priority INTEGER NOT NULL, Exclusive INTEGER NOT NULL, RequiresCode INTEGER NOT NULL, Value NUMERIC NOT NULL, BuyQuantity INTEGER NULL, PayQuantity INTEGER NULL, MinBasket NUMERIC NULL, Status TEXT NOT NULL, CreatedUtc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS PromotionScope (PromotionId INTEGER NOT NULL REFERENCES Promotion (Id) ON DELETE CASCADE, ScopeType TEXT NOT NULL, Value TEXT NOT NULL, PRIMARY KEY (PromotionId, ScopeType, Value));
CREATE INDEX IF NOT EXISTS IX_PriceList_Status_ValidFrom ON PriceList (Status, ValidFrom);
